package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.lang.StringUtils;
import org.apache.commons.lang.Validate;
import org.jsoup.Jsoup;
import org.jsoup.nodes.Element;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.Collector;
import org.jsoup.select.Elements;
import org.jsoup.select.Selector;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Element_prepend_TriageGen2Test {

    @Test
    public void testPrependWithValidHtml() {
        Element element = new Element("div", "");
        String html = "<p>Test</p>";
        element.prepend(html);
        Elements children = element.children();
        assertEquals(1, children.size());
        assertEquals("p", children.first().tagName());
        assertEquals("Test", children.first().text());
    }

    @Test(expected = NullPointerException.class)
    public void testPrependWithNullHtml() {
        Element element = new Element("div", "");
        element.prepend(null);
    }

    @Test
    public void testPrependWithEmptyHtml() {
        Element element = new Element("div", "");
        String html = "";
        element.prepend(html);
        assertEquals(0, element.children().size());
    }

    @Test
    public void testPrependWithMultipleNodes() {
        Element element = new Element("div", "");
        String html = "<p>First</p><span>Second</span>";
        element.prepend(html);
        Elements children = element.children();
        assertEquals(2, children.size());
        assertEquals("p", children.first().tagName());
        assertEquals("First", children.first().text());
        assertEquals("span", children.last().tagName());
        assertEquals("Second", children.last().text());
    }

    @Test
    public void testPrependWithNestedNodes() {
        Element element = new Element("div", "");
        String html = "<div><p>Inner</p></div>";
        element.prepend(html);
        Elements children = element.children();
        assertEquals(1, children.size());
        assertEquals("div", children.first().tagName());
        Elements innerChildren = children.first().children();
        assertEquals(1, innerChildren.size());
        assertEquals("p", innerChildren.first().tagName());
        assertEquals("Inner", innerChildren.first().text());
    }

    @Test
    public void testPrependToExistingChildren() {
        Element element = new Element("div", "");
        element.append("<p>Existing</p>");
        String html = "<span>New</span>";
        element.prepend(html);
        Elements children = element.children();
        assertEquals(2, children.size());
        assertEquals("span", children.first().tagName());
        assertEquals("New", children.first().text());
        assertEquals("p", children.last().tagName());
        assertEquals("Existing", children.last().text());
    }

    @Test
    public void testPrependWithWhitespace() {
        Element element = new Element("div", "");
        String html = "\n\t<p>Indented</p>\n";
        element.prepend(html);
        Elements children = element.children();
        assertEquals(1, children.size());
        assertEquals("p", children.first().tagName());
        assertEquals("Indented", children.first().text());
    }

    @Test
    public void testPrependWithInvalidHtml() {
        Element element = new Element("div", "");
        String html = "<p>Unclosed tag";
        element.prepend(html);
        Elements children = element.children();
        assertEquals(1, children.size());
        assertEquals("p", children.first().tagName());
        assertEquals("Unclosed tag", children.first().text());
    }

    @Test
    public void testPrependWithAttributes() {
        Element element = new Element("div", "");
        String html = "<p class='test'>WithClass</p>";
        element.prepend(html);
        Elements children = element.children();
        assertEquals(1, children.size());
        assertEquals("p", children.first().tagName());
        assertEquals("WithClass", children.first().text());
        assertEquals("test", children.first().className());
    }

    @Test
    public void testPrependWithDifferentTag() {
        Element element = new Element("div", "");
        String html = "<h1>Header</h1>";
        element.prepend(html);
        Elements children = element.children();
        assertEquals(1, children.size());
        assertEquals("h1", children.first().tagName());
        assertEquals("Header", children.first().text());
    }

    @Test
    public void testPrependWithTextAndElement() {
        Element element = new Element("div", "");
        element.prepend("Text ");
        element.prepend("<span>Span</span>");
        Elements children = element.children();
        assertEquals(2, children.size());
        assertEquals("span", children.first().tagName());
        assertEquals("Span", children.first().text());
        assertEquals("Text ", element.ownText());
    }
}
